// Cyrus game slots (D-63): how many GAMES an account may mod, per plan. PURE + client-safe; unit-tested in
// test/cyrus-game-slots.test.ts. The server half (usage from the DB, the race-safe claim) is ./game-slots.server.ts.
//
// RULES
//   slots        a plan has `games` slots (setting cyrus_tok_plan_<tier>_games; 0 = UNLIMITED). PLACEHOLDER defaults:
//                Free 1, Katara 1, Saka 3, All models unlimited.
//   in use       a game the account actually mods: it has at least one project or build in that game that is not
//                archived. The FIRST project in a new game takes a slot; the slot frees when every project in that game
//                is archived or deleted. Builds, changes, installs and exports inside a game already in use never ask.
//   enforcement  SERVER SIDE at every creation path (new build, change on an archived project, designer build, remix,
//                import, API v1 createProject / createBuild): plan / money gating, so it is HARD (D-62 keeps money hard),
//                with a plain message and the upgrade path. Off when the account is outside the token economy or
//                cyrus_tok_enforce is false (exactly like the model unlock), so preview / pre-launch behaviour is unchanged.
//   override     an admin can set an account's slots (JSON setting cyrus_game_slot_overrides, like cyrus_suspensions);
//                an override REPLACES the plan's number while it runs (it can raise or lower it), 0 = unlimited.
import type { TokenConfig, TokenTier } from "./config-pure";

export const UNLIMITED = 0;
export const GAME_SLOTS_FULL = "game_slots_full";
export const GAME_SLOT_OVERRIDES_KEY = "cyrus_game_slot_overrides";

/** The plan's slots (0 = unlimited). */
export const planGames = (tier: TokenTier, cfg: Pick<TokenConfig, "plan">): number => cfg.plan.games[tier] ?? 1;

export type GameSlotOverride = { userId: string; games: number; note: string; by: string; at: string; until: string | null };

/** Parse the stored JSON list (never throws; bad entries are dropped; one entry per account, the last wins). */
export function parseGameSlotOverrides(raw: string | null | undefined): GameSlotOverride[] {
  let v: unknown;
  try { v = JSON.parse(raw || "[]"); } catch { return []; }
  if (!Array.isArray(v)) return [];
  const byUser = new Map<string, GameSlotOverride>();
  for (const x of v) {
    if (!x || typeof x !== "object") continue;
    const r = x as Record<string, unknown>;
    if (typeof r.userId !== "string" || !/^[A-Za-z0-9_-]{1,64}$/.test(r.userId)) continue;
    const g = Number(r.games);
    if (!Number.isInteger(g) || g < 0 || g > 1000) continue;
    byUser.set(r.userId, {
      userId: r.userId, games: g, note: String(r.note ?? "").slice(0, 300), by: String(r.by ?? "").slice(0, 64),
      at: typeof r.at === "string" ? r.at : new Date(0).toISOString(),
      until: typeof r.until === "string" && !Number.isNaN(Date.parse(r.until)) ? r.until : null,
    });
  }
  return [...byUser.values()];
}

export const activeGameSlotOverride = (list: GameSlotOverride[], userId: string, now: Date): GameSlotOverride | null =>
  list.find((o) => o.userId === userId && (!o.until || Date.parse(o.until) > now.getTime())) ?? null;
export const upsertGameSlotOverride = (list: GameSlotOverride[], o: GameSlotOverride): GameSlotOverride[] => [...list.filter((x) => x.userId !== o.userId), o];
export const removeGameSlotOverride = (list: GameSlotOverride[], userId: string): GameSlotOverride[] => list.filter((x) => x.userId !== userId);
export const pruneGameSlotOverrides = (list: GameSlotOverride[], now: Date): GameSlotOverride[] => list.filter((o) => !o.until || Date.parse(o.until) > now.getTime());

/** The account's slots right now: an active override replaces the plan's number. */
export function gamesLimit(tier: TokenTier, cfg: Pick<TokenConfig, "plan">, override: GameSlotOverride | null): number {
  return override ? override.games : planGames(tier, cfg);
}

export type GameUsageRow = { game: string; archived: boolean };

/** Distinct games with at least one project/build that is not archived, in first-seen order. */
export function gamesInUse(rows: readonly GameUsageRow[]): string[] {
  const out: string[] = [];
  for (const r of rows) if (!r.archived && r.game && !out.includes(r.game)) out.push(r.game);
  return out;
}

export type GameSlotDecision =
  | { ok: true; takesSlot: boolean; used: number; limit: number }
  | { ok: false; code: typeof GAME_SLOTS_FULL; used: number; limit: number; inUse: string[]; error: string; upgrade: TokenTier | null };

/** The cheapest plan whose slots would fit one more game (null = none; then only an admin override helps). */
export function upgradeTierFor(usedCount: number, cfg: Pick<TokenConfig, "plan">, from: TokenTier): TokenTier | null {
  const order: TokenTier[] = ["free", "katara", "saka", "all"];
  for (const t of order.slice(order.indexOf(from) + 1)) {
    const g = planGames(t, cfg);
    if (g === UNLIMITED || g > usedCount) return t;
  }
  return null;
}

// Public, anonymous, cacheable: what the cyrus.my landing may truthfully say right now.
//   state   "closed" (private beta) | "public" (open, metered) | "unmetered" (invalid pair: treated as closed)
//   tokensLive  the token economy is live (plan numbers are real offers only then)
//   plans   the SAME rows the in-app Compare plans table shows (lib/cyrus/content/plan-table.ts, live settings + real
//           Stripe prices; price "To be announced" until a real price exists). No account data, no counters.
// Fails closed: any error answers state "closed" with no plans, so the page falls back to its static beta wording.
import { NextResponse } from "next/server";
import { getSettingBool } from "@/lib/settings";
import { launchState } from "@/lib/cyrus/launch-state";
import { livePlanColumns } from "@/lib/cyrus/content/plan-table.server";

export const dynamic = "force-dynamic";

export async function GET() {
  const headers = { "Cache-Control": "public, max-age=60, s-maxage=60" };
  try {
    const [studioPublic, tokensLive] = await Promise.all([getSettingBool("cyrus_studio_public_enabled", false), getSettingBool("cyrus_tok_live", false)]);
    const state = launchState({ studioPublic, tokensLive });
    const plans = await livePlanColumns().then((cols) => cols.map((c) => ({
      tier: c.tier, name: c.name, price: c.price, priceKnown: c.priceKnown, models: c.models, tokens: c.tokens, games: c.games, storage: c.storage,
    }))).catch(() => []);
    return NextResponse.json({ state: state === "unmetered" ? "closed" : state, tokensLive, plans }, { headers });
  } catch {
    return NextResponse.json({ state: "closed", tokensLive: false, plans: [] }, { headers });
  }
}
// Cyrus plan comparison (D-63/D-64): ONE table, generated from the LIVE settings so it never drifts from what the
// server enforces. PURE (server components pass the parsed configs in); unit-tested in test/cyrus-plan-table.test.ts.
// Rows: price, models, tokens per month (+ an estimate from the live reserve table), games you can mod, storage
// included, library access. RULES: no fabricated numbers. A price shows only when the real Stripe price was found
// (lookup key cyrus_plan_<tier>_v1, as the token screen does); otherwise "To be announced". Free has no monthly
// tokens: it shows the one-time starter grant.
import { canAsset } from "../engine-core/asset-gate";
import { CATALOG_KINDS, gateKindOf } from "../library/v2/entry";
import { PLAN_TIERS as LIBRARY_PLAN_TIERS } from "../library/v2/tools";
import { CYRUS_MODELS } from "../models";
import type { StorageConfig } from "../storage/config";
import { TIER_MODELS } from "../tokens/economy";
import type { PlanTier, TokenConfig, TokenTier } from "../tokens/config-pure";
import { gamesText } from "../tokens/game-slots";
import { fmtCount, planEstimates } from "../tokens/plan-estimates";

export const COMPARE_TIERS: readonly TokenTier[] = ["free", "katara", "saka", "all"];
export const COMPARE_NAME: Record<TokenTier, string> = { free: "Free", katara: "Katara", saka: "Saka", all: "Yakko" };

export type PlanColumn = {
  tier: TokenTier; name: string;
  price: string; priceKnown: boolean;
  models: string; tokens: string; estimate: string | null;
  games: string; gamesN: number;
  storage: string; storageGb: number;
  library: string;
};
export type PlanRowKey = "price" | "models" | "tokens" | "games" | "storage" | "library";
export const PLAN_ROWS: readonly { key: PlanRowKey; label: string }[] = [
  { key: "price", label: "Price" },
  { key: "models", label: "Models" },
  { key: "tokens", label: "Tokens" },
  { key: "games", label: "Games you can mod" },
  { key: "storage", label: "Storage included" },
  { key: "library", label: "Asset library" },
];

const n = (x: number) => Math.round(x).toLocaleString("en-US");
const money = (cents: number) => `$${(cents / 100).toFixed(cents % 100 ? 2 : 0)}`;
const gb = (x: number) => `${Number.isInteger(x) ? x : x.toFixed(1)} GB`;
const KIND_WORD: Record<string, string> = { sound: "sounds", texture: "textures", model: "3D models", ui: "UI art" };

/** What a plan may pick from the asset library (the SAME gate the build tools use: kinds by plan, licence tiers). */
export function libraryAccessText(tier: TokenTier): string {
  if (!LIBRARY_PLAN_TIERS[tier].length) return "Not included";
  const kinds = CATALOG_KINDS.filter((k) => canAsset(tier, gateKindOf(k), "create").ok);
  if (!kinds.length) return "Not included";
  if (kinds.length === CATALOG_KINDS.length) return "Every library";
  const words = [...new Set(kinds.map((k) => KIND_WORD[gateKindOf(k)] ?? gateKindOf(k)))];
  return words.length === 1 ? `${words[0][0].toUpperCase()}${words[0].slice(1)} only` : words.join(", ");
}

/** `prices`: real Stripe unit amounts in cents per paid tier (null / missing = not found = "To be announced"). */
export function planComparison(a: { tokens: TokenConfig; storage: Pick<StorageConfig, "quotaGb">; prices?: Partial<Record<PlanTier, number | null>>; /** CYRUS_STORAGE_ADDONS on */ addons?: boolean }): PlanColumn[] {
  return COMPARE_TIERS.map((tier): PlanColumn => {
    const models = TIER_MODELS[tier].map((m) => CYRUS_MODELS.find((x) => x.id === m)?.name ?? m);
    const monthly = tier === "free" ? 0 : a.tokens.plan.tokens[tier];
    const tokensFor = tier === "free" ? a.tokens.starterTokens : monthly;
    const top = tokensFor > 0 ? planEstimates(tokensFor, TIER_MODELS[tier], a.tokens.reserve)[0] : null;
    const cents = tier === "free" ? 0 : a.prices?.[tier] ?? null;
    const gamesN = a.tokens.plan.games[tier];
    return {
      tier, name: COMPARE_NAME[tier],
      price: tier === "free" ? "Free" : cents && cents > 0 ? `${money(cents)} a month` : "To be announced", priceKnown: tier === "free" || !!(cents && cents > 0),
      models: models.join(", "),
      tokens: tier === "free" ? (a.tokens.starterTokens > 0 ? `${n(a.tokens.starterTokens)} once, to try it` : "None") : `${n(monthly)} a month`,
      estimate: top ? `about ${fmtCount(top.small)} small mods on ${CYRUS_MODELS.find((x) => x.id === top.model)?.name ?? top.model}` : null,
      games: gamesText(gamesN), gamesN,
      storage: gb(a.storage.quotaGb[tier]) + (a.addons ? " (buy more any time)" : ""), storageGb: a.storage.quotaGb[tier],
      library: libraryAccessText(tier),
    };
  });
}

export function cellText(c: PlanColumn, k: PlanRowKey): string {
  return k === "tokens" ? c.tokens : c[k];
}
