export function gamesSettingWarnings(games: Record<TokenTier, number>): string[] {
  const eff = (n: number) => (n === UNLIMITED ? Number.POSITIVE_INFINITY : n);
  const out: string[] = [];
  const order: TokenTier[] = ["free", "katara", "saka", "all"];
  for (let i = 1; i < order.length; i++) {
    if (eff(games[order[i]]) < eff(games[order[i - 1]])) out.push(`${TIER_NAME[order[i]]} allows fewer games (${gamesText(games[order[i]])}) than ${TIER_NAME[order[i - 1]]} (${gamesText(games[order[i - 1]])}): an upgrade would take games away.`);
  }
  if (games.all !== UNLIMITED) out.push(`The top plan is not unlimited (${gamesText(games.all)}); the owner asked for unlimited.`);
  return out;
}
