  cyrus_storage_quota_katara_gb: ["Storage: Katara quota (GB)", "Included storage on Katara (owner: 5 GB)."],
  cyrus_storage_quota_saka_gb: ["Storage: Saka quota (GB)", "Included storage on Saka (owner: 25 GB)."],
  cyrus_storage_quota_all_gb: ["Storage: Yakko quota (GB)", "Included storage on Yakko, tier key all (owner: 50 GB)."],
  cyrus_storage_price_table: ["Storage: price bands (monthly)", "JSON list of {fromGb, centsPerGb}; the first band starts at 1 GB, bands go up. Owner's numbers: 1 GB 85c, 5 GB 75c, 25 GB 60c, 50 GB 30c, 100 GB 20c per GB."],
  cyrus_storage_pricing_rule: ["Storage: pricing rule", "capped = fewer GB never cost more than the next breakpoint (default, owner to confirm); literal = rate x GB with the 49/50 GB cliff; graduated = each GB at its own band's rate."],
  cyrus_storage_addon_max_gb: ["Storage: largest add-on (GB)", "Most extra GB one account may buy."],
  cyrus_storage_grace_days: ["Storage: grace after a quota drop (days)", "After a downgrade, cancel, refund or failed renewal an over-quota account keeps writing this long; then new builds and uploads stop until it is under quota. Data is never deleted automatically."],
  const usdPaid = cents / 100;
  const tokens = Math.round(usdPaid * cfg.topup.tokensPerUsd);
  const minMult = Math.min(...Object.values(cfg.mult));
  const cost = tokens / (cfg.tokensPerUsd * minMult);
  const fee = (usdPaid * fees.stripePct) / 100 + fees.stripeFixedCents / 100;
  const after = usdPaid - cost - fee;
  return { paidUsd: usdPaid, tokens, worstCostUsd: r2(cost), feeUsd: r2(fee), marginAfterFeesUsd: r2(after), marginAfterFeesPct: usdPaid > 0 ? (after / usdPaid) * 100 : 0 };
}

