  "cyrus_tok_starter", "cyrus_tok_topup_tokens_per_usd",
  // D-63 games per plan (0 = unlimited): no effect on the margin preview, edited here so plans are tuned in one place
  "cyrus_tok_plan_free_games", "cyrus_tok_plan_katara_games", "cyrus_tok_plan_saka_games", "cyrus_tok_plan_all_games",
  "cyrus_econ_stripe_pct", "cyrus_econ_stripe_fixed_cents", "cyrus_econ_margin_warn_pct",
] as const;
export type EconEditKey = (typeof ECON_EDIT_KEYS)[number];

/** Stored settings + an unsaved draft -> the projected economy (what the preview shows before saving). */
export function previewEconomics(stored: Partial<Record<string, string>>, draft: Partial<Record<string, string>>, costs: Record<CyrusModelId, ModelCost>) {
  const merged: Record<string, string | undefined> = { ...stored };
  for (const [k, v] of Object.entries(draft)) if (v !== undefined) merged[k] = v;
  const cfg = parseTokenConfig(merged);
  const fees = parseEconFees(merged);
  return { cfg, fees, plans: planEconomics({ cfg, fees, costs }), starter: starterCost(cfg), topup: topupMargin(cfg, fees) };
}

