/* CYRUS landing v7: a black-and-white instrument language with electric blue + violet energy. */
@font-face{font-family:"Grotesk";src:url(../fonts/sg-500.woff2) format("woff2");font-weight:500;font-display:swap}
@font-face{font-family:"Grotesk";src:url(../fonts/sg-600.woff2) format("woff2");font-weight:600 700;font-display:swap}
@font-face{font-family:"Inter";src:url(../fonts/inter-400.woff2) format("woff2");font-weight:400;font-display:swap}
@font-face{font-family:"Inter";src:url(../fonts/inter-600.woff2) format("woff2");font-weight:500 700;font-display:swap}
@font-face{font-family:"Mono";src:url(../fonts/jb-400.woff2) format("woff2");font-weight:400;font-display:swap}
@font-face{font-family:"Mono";src:url(../fonts/jb-500.woff2) format("woff2");font-weight:500 700;font-display:swap}

:root{
  --bg:#000;--ink:#fff;--ink-2:rgba(255,255,255,.74);--ink-3:rgba(255,255,255,.56);--ink-4:rgba(255,255,255,.5);
  --line:rgba(255,255,255,.09);--line-2:rgba(255,255,255,.16);
  --blue:#3d7bff;--blue-hi:#79a6ff;--violet:#8b5cff;--violet-hi:#b49bff;
  --glass:rgba(255,255,255,.035);--glass-2:rgba(255,255,255,.06);
  --energy:linear-gradient(100deg,var(--blue),var(--violet));
  --r:18px;--r-sm:12px;--gut:clamp(16px,4vw,48px);--max:1240px;
  --display:"Grotesk","Inter",system-ui,sans-serif;--body:"Inter",system-ui,sans-serif;--mono:"Mono",ui-monospace,monospace;
  color-scheme:dark;
}
*,*::before,*::after{box-sizing:border-box}
html{scroll-behavior:smooth;-webkit-text-size-adjust:100%}
body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.55 var(--body);-webkit-font-smoothing:antialiased;overflow-x:hidden}
img,svg,canvas{display:block;max-width:100%}
button,input,select,textarea{font:inherit;color:inherit}
button{cursor:pointer}
a{color:inherit}
::selection{background:var(--violet);color:#fff}
:focus-visible{outline:2px solid var(--blue-hi);outline-offset:3px;border-radius:6px}
.sr-only{position:absolute!important;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap;border:0}
.skip{position:fixed;left:16px;top:-60px;z-index:100;background:#fff;color:#000;padding:10px 14px;border-radius:10px;font-weight:600;text-decoration:none}
.skip:focus{top:12px}
.wrap{width:100%;max-width:var(--max);margin:0 auto;padding:0 var(--gut)}
.mono{font-family:var(--mono);letter-spacing:.02em}
.grad-text{background:var(--energy);-webkit-background-clip:text;background-clip:text;color:transparent}

/* ---------- nav ---------- */
.nav{position:fixed;inset:0 0 auto 0;z-index:50;transition:background .4s,border-color .4s,backdrop-filter .4s;border-bottom:1px solid transparent}
.nav.scrolled{background:rgba(0,0,0,.62);backdrop-filter:blur(16px) saturate(140%);-webkit-backdrop-filter:blur(16px) saturate(140%);border-color:var(--line)}
.nav .wrap{display:flex;align-items:center;gap:28px;height:68px}
.brand{display:flex;align-items:center;gap:10px;text-decoration:none}
.brand img{height:22px;width:auto}
.g b{font:600 14px var(--display)}
.g small{position:absolute;top:10px;right:10px;font:500 9px var(--mono);letter-spacing:.16em;text-transform:uppercase;color:var(--ink-4);border:1px solid var(--line-2);border-radius:999px;padding:2px 7px}

/* plans */
.plans{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}
.plan{position:relative;border-radius:24px;padding:28px 26px 26px;border:1px solid var(--line);background:linear-gradient(180deg,rgba(255,255,255,.045),rgba(255,255,255,.01));display:flex;flex-direction:column;overflow:hidden;transition:transform .6s cubic-bez
.plan:hover{transform:translateY(-6px);border-color:var(--line-2)}
.plan::after{content:"";position:absolute;left:-20%;right:-20%;top:-60%;height:80%;background:radial-gradient(closest-side,var(--tint),transparent);opacity:.18;pointer-events:none;transition:opacity .5s}
.plan:hover::after{opacity:.32}
.plan.katara{--tint:#3d7bff}.plan.saka{--tint:#6a6cff}.plan.yakko{--tint:#8b5cff}
.plan .sig{width:96px;height:96px;margin-bottom:22px}
.plan .tier{font:500 10px var(--mono);letter-spacing:.22em;text-transform:uppercase;color:var(--ink-4)}
.plan h3{font-size:32px;letter-spacing:-.03em;margin:6px 0 4px}
.plan .lead{margin:0 0 20px;color:var(--ink-2);font-size:15px}
.plan ul{list-style:none;margin:0 0 26px;padding:0;display:grid;gap:10px;font-size:14px;color:var(--ink-2)}
.plan li{display:flex;gap:10px;align-items:flex-start}
.plan li svg{flex:none;width:16px;height:16px;margin-top:2px;color:var(--blue-hi)}
.plan li.dim{color:var(--ink-4)}
.plan li.dim svg{color:var(--ink-4)}
.plan .btn{margin-top:auto}
.plan.yakko{border-color:rgba(139,92,255,.35)}
.free{margin-top:16px;border-radius:18px;border:1px dashed var(--line-2);padding:16px 22px;display:flex;align-items:center;gap:16px;flex-wrap:wrap;color:var(--ink-2);font-size:15px}
.free b{font:600 16px var(--display);color:#fff}
.free .btn{margin-left:auto}

/* plan icons */
.sig .w1{animation:wave 5s linear infinite}.sig .w2{animation:wave 3.4s linear infinite reverse}.sig .w3{animation:wave 7s linear infinite}
@keyframes wave{to{transform:translateX(-48px)}}
.sig .bob{animation:bob 4s ease-in-out infinite;transform-origin:48px 48px}
@keyframes bob{50%{transform:translateY(-2px)}}
.sig .fl1{transform-origin:48px 78px;animation:flick 2.2s ease-in-out infinite}
.sig .fl2{transform-origin:48px 78px;animation:flick 1.7s ease-in-out infinite reverse}
.sig .fl3{transform-origin:48px 78px;animation:flick 1.3s ease-in-out infinite}
@keyframes flick{0%,100%{transform:scale(1,1) skewX(0)}30%{transform:scale(.97,1.05) skewX(-3deg)}65%{transform:scale(1.03,.96) skewX(3deg)}}
.sig .em{animation:rise 2.6s ease-in infinite;opacity:0}
.sig .em:nth-of-type(2){animation-delay:.9s}.sig .em:nth-of-type(3){animation-delay:1.7s}
@keyframes rise{0%{transform:translateY(0);opacity:0}20%{opacity:1}100%{transform:translateY(-34px);opacity:0}}
.sig .r1{transform-origin:48px 48px;animation:rot 18s linear infinite}
.sig .r2{transform-origin:48px 48px;animation:rot 12s linear infinite reverse}
.sig .spark{transform-origin:48px 48px;animation:spark 2.8s ease-in-out infinite}
@keyframes spark{0%,100%{transform:scale(.86) rotate(0);opacity:.85}50%{transform:scale(1.08) rotate(45deg);opacity:1}}

/* bridge */
.bridge{display:grid;grid-template-columns:minmax(0,5fr) minmax(0,7fr);gap:clamp(24px,4vw,64px);align-items:center}
.bridge-copy .btn-nx{margin-top:26px;--h:52px;padding:0 22px 0 14px;background:#0b0b10;border-color:rgba(255,255,255,.22)}
footer nav a{color:var(--ink-3);text-decoration:none;font-size:14px}
footer nav a:hover{color:#fff}
footer .copy{width:100%;font:400 12px var(--mono);color:var(--ink-3)}

.toast{position:fixed;left:50%;bottom:24px;z-index:90;transform:translate(-50%,30px);opacity:0;pointer-events:none;padding:12px 18px;border-radius:14px;background:rgba(16,16,22,.95);border:1px solid v
.toast.show{opacity:1;transform:translate(-50%,0)}

/* ---------- responsive ---------- */
