  .soon{grid-template-columns:repeat(2,minmax(0,1fr))}
  .loops,.loops.fxrow{grid-template-columns:repeat(2,minmax(0,1fr))}
  .c-tex .paint{grid-template-columns:minmax(0,1fr)}
  .c-tex .side{display:grid;grid-template-columns:minmax(0,1fr) 112px;gap:14px;align-items:start}
