   The static page already carries honest private-beta wording and no numbers. When the app answers, the wording follows
   the real launch flags and the plan cards show the real numbers (never invented: only fields the app sent). */
(() => {
  const note = $('#launchNote'), pn = $('#plansNote');
  const esc = (t) => String(t).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
  if (!note || !window.fetch) return;
  fetch('/api/cyrus/launch', { headers: { accept: 'application/json' } }).then((r) => (r.ok ? r.json() : null)).then((j) => {
    if (!j || (j.state !== 'closed' && j.state !== 'public')) return;
    if (j.state === 'public') note.textContent = 'Sign in or create an account with your Nxeon login. Your prompt carries through.';
    if (!Array.isArray(j.plans) || !j.plans.length) return;
    // Fill every [data-t][data-k] (cards + comparison table) from the app's live plan rows; only fields it sent.
    const val = { price: (p) => (p.priceKnown ? p.price : 'To be announced'), tokens: (p) => String(p.tokens || '').replace(/^([\d,]+)/, '$1 tokens') };
    j.plans.forEach((p) => {
      $$(`[data-t="${p.tier}"][data-k]`).forEach((el) => {
        const k = el.dataset.k; const v = val[k] ? val[k](p) : p[k];
        if (v === undefined || v === null || v === '') return;
        el.textContent = v;
        if (k === 'tokens' && p.estimate) { const s = document.createElement('small'); s.textContent = p.estimate; el.appendChild(s); }
      });
      if (p.tier === 'free') { const f = $('#freeText'); if (f && p.tokens && p.tokens !== 'None') f.textContent = `Free: ${String(p.tokens).replace(/^([\d,]+)/, '$1 tokens')}.`; }
    });
    const badge = $('#plansBadge');
    if (j.numbersFinal) pn.textContent = 'Plan numbers are final. Tokens pay for builds; unused tokens roll over while you stay subscribed.';
    else if (badge) badge.hidden = false;
    if (!j.tokensLive) return;
    const rules = $('#planRules'); if (rules) rules.hidden = false;
  }).catch(() => {});
})();
/* ================= GAMEPLAY GALLERY ================= */
(() => {
  const tr = $('#gpTrack'); if (!tr) return;
  const step = () => (tr.querySelector('.gp-item')?.getBoundingClientRect().width || 300) + 16;
  const go = (d) => tr.scrollBy({ left: d * step(), behavior: reduce ? 'auto' : 'smooth' });
  $('#gpPrev').addEventListener('click', () => go(-1)); $('#gpNext').addEventListener('click', () => go(1));
  tr.addEventListener('keydown', (e) => { if (e.key === 'ArrowRight') { e.preventDefault(); go(1); } if (e.key === 'ArrowLeft') { e.preventDefault(); go(-1); } });
})();
})();

