// Cyrus item model states: per-CATEGORY display defaults for all 8 display contexts + the owner's overrides. Pure and
// client-safe (the Texture Studio preview applies exactly these numbers). Vanilla values, verified 2026-10-10 against
// the vanilla asset mirror (github.com/InventivetalentDev/minecraft-assets, branches 1.21.4, 1.21.11 and 26.2: the
// files models/item/{generated,handheld,bow,crossbow}.json are byte-identical in canonical form across the three):
//   item/generated  ground [0,0,0]/[0,2,0]/0.5, head [0,180,0]/[0,13,7]/1, thirdperson_righthand [0,0,0]/[0,3,1]/0.55,
//                   firstperson_righthand [0,-90,25]/[1.13,3.2,1.13]/0.68, fixed [0,180,0]/-/1 (no gui, no left hands)
//   item/handheld   the four hands (lib/cyrus/textures/display.ts HANDHELD_DISPLAY), the rest from generated
//   item/bow        thirdperson_righthand [-80,260,-40]/[-1,-2,2.5]/0.9, lefthand [-80,-280,40]/same,
//                   firstperson_righthand [0,-90,25]/[1.13,3.2,1.13]/0.68, lefthand [0,90,-25]/same
//   item/crossbow   thirdperson_righthand [-90,0,-60]/[2,0.1,-3]/0.9, lefthand [-90,0,30]/same,
//                   firstperson_righthand [-90,0,-55]/[1.13,3.2,1.13]/0.68, lefthand [-90,0,35]/same
// A context the model does not define: the game uses no transform (identity), except a missing left hand, which takes
// the right hand's transform (ItemTransforms deserializer). Cyrus always writes all 8 contexts explicitly with exactly
// those fallbacks, so the result does not depend on parent-chain merging.
// Cyrus (not vanilla) defaults: gun = the handgun rotations + re-grip of lib/cyrus/textures/display.ts (UNVERIFIED in a
// client); wand = handheld; shield = generated (a flat shield sprite; vanilla's shield is a special entity model);
// sword/tool = handheld. All UNVERIFIED in a real client except where they equal vanilla.
import type { Raster } from "../textures/render";
import { displayFor, HANDHELD_DISPLAY, type DisplayOpts, type DisplayTransform, type Vec3 } from "../textures/display";
import { DISPLAY_CONTEXTS, ITEMMODEL_CAPS, type Category, type DisplayContext, type DisplayOverride } from "./spec";

export type FullDisplay = Record<DisplayContext, DisplayTransform>;

const T = (rotation: Vec3, translation: Vec3, s: number): DisplayTransform => ({ rotation, translation, scale: [s, s, s] });
const ID = (): DisplayTransform => T([0, 0, 0], [0, 0, 0], 1);

export const GENERATED_FULL: FullDisplay = {
  gui: ID(),
  ground: T([0, 0, 0], [0, 2, 0], 0.5),
  fixed: T([0, 180, 0], [0, 0, 0], 1),
  head: T([0, 180, 0], [0, 13, 7], 1),
  firstperson_righthand: T([0, -90, 25], [1.13, 3.2, 1.13], 0.68),
  firstperson_lefthand: T([0, -90, 25], [1.13, 3.2, 1.13], 0.68), // missing left = right (deserializer fallback)
  thirdperson_righthand: T([0, 0, 0], [0, 3, 1], 0.55),
  thirdperson_lefthand: T([0, 0, 0], [0, 3, 1], 0.55),
};
const withHands = (hands: Pick<FullDisplay, "firstperson_righthand" | "firstperson_lefthand" | "thirdperson_righthand" | "thirdperson_lefthand">): FullDisplay => ({ ...GENERATED_FULL, ...hands });
export const HANDHELD_FULL: FullDisplay = withHands(HANDHELD_DISPLAY);
export const BOW_FULL: FullDisplay = withHands({
  thirdperson_righthand: T([-80, 260, -40], [-1, -2, 2.5], 0.9),
  thirdperson_lefthand: T([-80, -280, 40], [-1, -2, 2.5], 0.9),
  firstperson_righthand: T([0, -90, 25], [1.13, 3.2, 1.13], 0.68),
  firstperson_lefthand: T([0, 90, -25], [1.13, 3.2, 1.13], 0.68),
});
export const CROSSBOW_FULL: FullDisplay = withHands({
  thirdperson_righthand: T([-90, 0, -60], [2, 0.1, -3], 0.9),
  thirdperson_lefthand: T([-90, 0, 30], [2, 0.1, -3], 0.9),
  firstperson_righthand: T([-90, 0, -55], [1.13, 3.2, 1.13], 0.68),
  firstperson_lefthand: T([-90, 0, 35], [1.13, 3.2, 1.13], 0.68),
});

/** Where each category's defaults come from (shown in the studio and the docs). */
export const CATEGORY_SOURCE: Record<Category, string> = {
  sword: "vanilla item/handheld", tool: "vanilla item/handheld", wand: "vanilla item/handheld (Cyrus choice)", bow: "vanilla item/bow",
  crossbow: "vanilla item/crossbow", gun: "Cyrus handgun rotations, re-gripped (unverified in a client)", shield: "vanilla item/generated (flat sprite, Cyrus choice)", flat: "vanilla item/generated",
};

const clone = (d: FullDisplay): FullDisplay => Object.fromEntries(DISPLAY_CONTEXTS.map((c) => [c, { rotation: [...d[c].rotation], translation: [...d[c].translation], scale: [...d[c].scale] }])) as FullDisplay;

/** The category's default display. `gun` needs the idle raster (its grip is found on the pixels); without it the tool grip is used. */
export function categoryDisplay(category: Category, idle?: Raster, name = "gun", opts: DisplayOpts = {}): FullDisplay {
  switch (category) {
    case "bow": return clone(BOW_FULL);
    case "crossbow": return clone(CROSSBOW_FULL);
    case "shield": case "flat": return clone(GENERATED_FULL);
    case "gun": {
      // displayFor re-grips only names that read as a handgun; force it for the gun category
      const hands = idle ? displayFor(`${name}_gun`, idle, opts) : HANDHELD_DISPLAY;
      return clone(withHands(hands));
    }
    default: return clone(HANDHELD_FULL);
  }
}

const r3 = (v: number) => Math.round(v * 1000) / 1000 || 0; // no -0 in JSON
const capV = (v: Vec3, cap: number): Vec3 => [r3(Math.max(-cap, Math.min(cap, v[0]))), r3(Math.max(-cap, Math.min(cap, v[1]))), r3(Math.max(-cap, Math.min(cap, v[2])))];

/** base display + overrides (later wins, per context and field); every number capped like the game and rounded. */
export function mergeDisplay(base: FullDisplay, ...overrides: (DisplayOverride | undefined)[]): FullDisplay {
  const out = clone(base);
// Cyrus item model states: the Texture Studio's CONTEXT switcher + STATE scrubber, pure + client-safe (no DOM).
// For the current texture it finds the mod's ItemModelSpec (or derives the default the pack uses for a texture without
// one: tool = handheld, a handgun name = gun), lists its states, and draws the extruded item through the SAME display
// transforms the pack writes (./emit.ts stateDisplays) in six views: hotbar slot (gui), dropped (ground), first and
// third person (lib/cyrus/studios/held.ts with the transform), item frame (fixed), head. Cameras, the slot / frame /
// shadow / head backdrops and the head-layer offset are Cyrus's approximation of the game renderer: "approximate".
import type { Raster } from "../textures/render";
import { applyDisplay, gripKindOf, type DisplayTransform, type Vec3 } from "../textures/display";
import { heldScene, type Poly } from "../studios/held";
import { stateDisplays } from "./emit";
import type { DisplayContext, ItemModelSpec, ItemState } from "./spec";
import type { FullDisplay } from "./display";

export type PreviewContext = "gui" | "ground" | "firstperson" | "thirdperson" | "fixed" | "head";
export const PREVIEW_CONTEXTS: { id: PreviewContext; label: string; display: DisplayContext; hint: string }[] = [
  { id: "gui", label: "Hotbar", display: "gui", hint: "In an inventory slot, with the gui transform" },
  { id: "ground", label: "Dropped", display: "ground", hint: "Dropped on the ground, with the ground transform" },
  { id: "firstperson", label: "First person", display: "firstperson_righthand", hint: "First person, right hand, with the pack's display transform" },
  { id: "thirdperson", label: "Third person", display: "thirdperson_righthand", hint: "Third person, right hand, with the pack's display transform" },
  { id: "fixed", label: "Item frame", display: "fixed", hint: "In an item frame, with the fixed transform" },
  { id: "head", label: "Head", display: "head", hint: "Worn on the head, with the head transform" },
];

export type PreviewState = { id: string; label: string; texture: string };
export type PreviewModel = { spec: ItemModelSpec; derived: boolean; states: PreviewState[] };

const cap = (s: string) => s.replace(/_/g, " ").replace(/^./, (c) => c.toUpperCase());
/** Scrubber label: the spec's label, else from the condition (Pull 1-3, Use, Reload...). */
export function stateLabel(st: ItemState, all: ItemState[]): string {
  if (st.label) return st.label;
  const w = st.when;
  if (w.type === "pull") { const i = all.filter((x) => x.when.type === "pull").sort((a, b) => (a.when as { from: number }).from - (b.when as { from: number }).from).indexOf(st); return `Pull ${i + 1}`; }
  if (w.type === "using") return "Use";
  if (w.type === "mode") return cap(w.value);
  if (w.type === "flag") return cap(w.name);
  if (w.type === "charged") return w.charge === "arrow" ? "Loaded" : "Rocket";
  return cap(st.id);
}

/** The item model a texture belongs to (as idle or as a state texture), else the pack's default for it. */
export function previewModel(cur: string, specs: readonly ItemModelSpec[]): PreviewModel {
  const spec = specs.find((s) => s.name === cur) ?? specs.find((s) => (s.states ?? []).some((x) => x.texture === cur));
  if (!spec) return { spec: { schemaVersion: 1, name: cur, category: gripKindOf(cur) === "handgun" ? "gun" : "tool" }, derived: true, states: [{ id: "idle", label: "Idle", texture: cur }] };
  const st = spec.states ?? [];
  return { spec, derived: false, states: [{ id: "idle", label: "Idle", texture: spec.name }, ...st.map((s) => ({ id: s.id, label: stateLabel(s, st), texture: s.texture }))] };
}

