export type GripKind = "tool" | "handgun";
export const TOOL_HANDLE: [number, number] = [2.5, 1.5];
const GUN = /(^|_)(glock|pistol|handgun|revolver|gun|blaster|rifle|smg|shotgun|musket|flintlock|deagle|uzi)(_|$|\d)/;
export const gripKindOf = (name: string): GripKind => (GUN.test(name) ? "handgun" : "tool");

export function gripPoint(r: Raster, kind: GripKind): [number, number] {
  if (kind === "tool") return TOOL_HANDLE;
  const n = r.size, k = 16 / n;
  let x0 = n, x1 = -1, y0 = n, y1 = -1;
  for (let y = 0; y < n; y++) for (let x = 0; x < n; x++) if (r.px[(y * n + x) * 4 + 3]) { x0 = Math.min(x0, x); x1 = Math.max(x1, x); y0 = Math.min(y0, y); y1 = Math.max(y1, y); }
  if (x1 < 0) return TOOL_HANDLE;
  const yCut = y1 - (y1 - y0 + 1) * 0.4, xCut = x0 + (x1 - x0 + 1) * 0.6;
  let sx = 0, sy = 0, c = 0;
  for (let y = 0; y < n; y++) for (let x = 0; x < n; x++) if (r.px[(y * n + x) * 4 + 3] && y >= yCut && x <= xCut) { sx += x + 0.5; sy += y + 0.5; c++; }
  if (!c) return TOOL_HANDLE;
  return [round3((sx / c) * k), round3(16 - (sy / c) * k)];
}

