/** Clip time (ticks, 0..length) of a local tick, by loop mode. once/hold clamp; loop wraps; pingpong reflects. */
export function clipTime(clip: Pick<Clip, "length" | "loop">, tick: number): number {
  const L = clip.length;
  if (tick <= 0) return 0;
  switch (clip.loop) {
    case "loop": { const m = tick % L; return m; }
    case "pingpong": { const m = tick % (2 * L); return m <= L ? m : 2 * L - m; }
    default: return Math.min(tick, L);
  }
}

function keyed(track: TransformTrack, t: number): Vec3 {
  const ks = track.keys!;
  if (t <= ks[0].t) return [...ks[0].v] as Vec3;
  const last = ks[ks.length - 1];
  if (t >= last.t) return [...last.v] as Vec3;
  let i = 0;
  while (i < ks.length - 2 && t >= ks[i + 1].t) i++;
  const a = ks[i], b = ks[i + 1];
  const f = b.t === a.t ? 1 : clamp((t - a.t) / (b.t - a.t), 0, 1);
  const e = ease(b.ease, f);
  return [lerp(a.v[0], b.v[0], e), lerp(a.v[1], b.v[1], e), lerp(a.v[2], b.v[2], e)];
}

