function put(r: Raster, x: number, y: number, c: Vec3, a = 1) {
  if (x < 0 || y < 0 || x >= r.w || y >= r.h) return;
  const i = (y * r.w + x) * 4;
  r.px[i] = r.px[i] + (c[0] - r.px[i]) * a; r.px[i + 1] = r.px[i + 1] + (c[1] - r.px[i + 1]) * a; r.px[i + 2] = r.px[i + 2] + (c[2] - r.px[i + 2]) * a; r.px[i + 3] = 255;
}
function add(r: Raster, x: number, y: number, c: Vec3, a: number) {
  if (x < 0 || y < 0 || x >= r.w || y >= r.h) return;
  const i = (y * r.w + x) * 4;
  r.px[i] = Math.min(255, r.px[i] + c[0] * a); r.px[i + 1] = Math.min(255, r.px[i + 1] + c[1] * a); r.px[i + 2] = Math.min(255, r.px[i + 2] + c[2] * a); r.px[i + 3] = 255;
}
export function fillRect(r: Raster, x0: number, y0: number, w: number, h: number, hex: string, a = 1) {
  const c = hexToRgb(hex);
  for (let y = Math.max(0, y0); y < Math.min(r.h, y0 + h); y++) for (let x = Math.max(0, x0); x < Math.min(r.w, x0 + w); x++) put(r, x, y, c, a);
}

