export type Camera = { eye: Vec3; target: Vec3; fov: number };
type View = { project: (p: Vec3) => { x: number; y: number; z: number } | null; light: Vec3 };
function view(cam: Camera, w: number, h: number): View {
  const f = [cam.target[0] - cam.eye[0], cam.target[1] - cam.eye[1], cam.target[2] - cam.eye[2]];
  const fl = Math.hypot(f[0], f[1], f[2]); const fw: Vec3 = [f[0] / fl, f[1] / fl, f[2] / fl];
  const up: Vec3 = [0, 1, 0];
  const rx: Vec3 = [fw[1] * up[2] - fw[2] * up[1], fw[2] * up[0] - fw[0] * up[2], fw[0] * up[1] - fw[1] * up[0]];
  const rl = Math.hypot(...rx); rx[0] /= rl; rx[1] /= rl; rx[2] /= rl;
  const uy: Vec3 = [rx[1] * fw[2] - rx[2] * fw[1], rx[2] * fw[0] - rx[0] * fw[2], rx[0] * fw[1] - rx[1] * fw[0]];
  const focal = (h / 2) / Math.tan((cam.fov * Math.PI) / 360);
  return {
    project: (p) => {
      const d = [p[0] - cam.eye[0], p[1] - cam.eye[1], p[2] - cam.eye[2]];
      const z = d[0] * fw[0] + d[1] * fw[1] + d[2] * fw[2];
      if (z < 0.05) return null;
      const x = d[0] * rx[0] + d[1] * rx[1] + d[2] * rx[2], y = d[0] * uy[0] + d[1] * uy[1] + d[2] * uy[2];
      return { x: w / 2 + (x * focal) / z, y: h / 2 - (y * focal) / z, z };
    },
    light: (() => { const l = [-0.45, 0.85, 0.35]; const n = Math.hypot(...l); return [l[0] / n, l[1] / n, l[2] / n] as Vec3; })(),
  };
}
